import type { SupabaseClient } from '@supabase/supabase-js';
import { expectTypeOf } from 'expect-type';
import { observable } from '../src/observable';
import { syncedSupabase } from '../src/sync-plugins/supabase';

type TodoRow = { id: number; text: string; done: boolean | null; owner_id: string };
type ProfileRow = { id: string; name: string };
type NoteRow = { id: string; body: string };

// Shape of a database type generated by the Supabase CLI
type Database = {
    public: {
        Tables: {
            todos: {
                Row: TodoRow;
                Insert: { id?: number; text: string; done?: boolean | null; owner_id: string };
                Update: { id?: number; text?: string; done?: boolean | null; owner_id?: string };
                Relationships: [
                    {
                        foreignKeyName: 'todos_owner_id_fkey';
                        columns: ['owner_id'];
                        isOneToOne: false;
                        referencedRelation: 'profiles';
                        referencedColumns: ['id'];
                    },
                ];
            };
            profiles: {
                Row: ProfileRow;
                Insert: { id: string; name: string };
                Update: { id?: string; name?: string };
                Relationships: [];
            };
        };
        Views: { [_ in never]: never };
        Functions: { [_ in never]: never };
        Enums: { [_ in never]: never };
        CompositeTypes: { [_ in never]: never };
    };
    other: {
        Tables: {
            notes: {
                Row: NoteRow;
                Insert: { id?: string; body: string };
                Update: { id?: string; body?: string };
                Relationships: [];
            };
        };
        Views: { [_ in never]: never };
        Functions: { [_ in never]: never };
        Enums: { [_ in never]: never };
        CompositeTypes: { [_ in never]: never };
    };
};

declare const supabase: SupabaseClient<Database>;

describe('syncedSupabase types', () => {
    it('infers rows from the collection', () => {
        function todos() {
            return observable(syncedSupabase({ supabase, collection: 'todos' }));
        }
        function profilesArray() {
            return observable(syncedSupabase({ supabase, collection: 'profiles', as: 'array' }));
        }
        function badCollection() {
            // @ts-expect-error not a table in the schema
            return syncedSupabase({ supabase, collection: 'nope' });
        }

        expectTypeOf<ReturnType<ReturnType<typeof todos>['get']>>().toEqualTypeOf<Record<number, TodoRow>>();
        expectTypeOf<ReturnType<ReturnType<typeof profilesArray>['get']>>().toEqualTypeOf<ProfileRow[]>();
        expectTypeOf(badCollection).toBeFunction();
    });

    it('types the filter builder with the table rows', () => {
        function filtered() {
            return syncedSupabase({
                supabase,
                collection: 'todos',
                filter: (select, params) => {
                    expectTypeOf(params.value).toMatchTypeOf<TodoRow[] | undefined>();
                    expectTypeOf<Awaited<typeof select>['data']>().toEqualTypeOf<TodoRow[] | null>();
                    return select.eq('done', false).order('id', { ascending: true });
                },
            });
        }

        expectTypeOf<ReturnType<typeof filtered>>().toEqualTypeOf<Record<number, TodoRow>>();
    });

    it('types the select query builder with the table and columns', () => {
        function selected() {
            return syncedSupabase({
                supabase,
                collection: 'todos',
                select: (from) => from.select('id,text,done,owner_id').eq('owner_id', 'a'),
            });
        }
        function selectedAll() {
            return syncedSupabase({
                supabase,
                collection: 'todos',
                select: (from) => from.select(),
            });
        }

        expectTypeOf<ReturnType<typeof selected>>().toEqualTypeOf<Record<number, TodoRow>>();
        expectTypeOf<ReturnType<typeof selectedAll>>().toEqualTypeOf<Record<number, TodoRow>>();
    });

    it('infers rows from the select result with joins and column subsets', () => {
        function joined() {
            return syncedSupabase({
                supabase,
                collection: 'todos',
                select: (from) => from.select('*, profiles(*)'),
            });
        }
        function subset() {
            return syncedSupabase({
                supabase,
                collection: 'todos',
                select: (from) => from.select('id,text'),
            });
        }
        function badColumn() {
            // @ts-expect-error nope is not a column of todos
            return syncedSupabase({
                supabase,
                collection: 'todos',
                select: (from) => from.select('id,nope'),
            });
        }
        function filteredSubset() {
            return syncedSupabase({
                supabase,
                collection: 'todos',
                filter: (select) => select.eq('done', true),
                select: (from) => from.select('id,text'),
            });
        }

        expectTypeOf<ReturnType<typeof joined>>().toEqualTypeOf<
            Record<number, { id: number; text: string; done: boolean | null; owner_id: string; profiles: ProfileRow }>
        >();
        expectTypeOf(badColumn).toBeFunction();
        expectTypeOf<ReturnType<typeof subset>>().toEqualTypeOf<Record<number, { id: number; text: string }>>();
        expectTypeOf<ReturnType<typeof filteredSubset>>().toEqualTypeOf<Record<number, { id: number; text: string }>>();
    });

    it('types custom list, create, update and delete with the row type', () => {
        function custom() {
            return syncedSupabase({
                supabase,
                collection: 'todos',
                list: () => supabase.from('todos').select(),
                create: (input) => {
                    expectTypeOf(input).toEqualTypeOf<TodoRow>();
                    return supabase.from('todos').insert(input).select().single();
                },
                update: (input) => {
                    expectTypeOf(input).toEqualTypeOf<Partial<TodoRow>>();
                    return supabase.from('todos').update(input).eq('id', input.id!).select().single();
                },
                delete: (input) => {
                    expectTypeOf(input).toEqualTypeOf<TodoRow>();
                    return supabase.from('todos').delete().eq('id', input.id).select().single();
                },
            });
        }

        expectTypeOf<ReturnType<typeof custom>>().toEqualTypeOf<Record<number, TodoRow>>();
    });

    it('infers rows from a non-public schema', () => {
        function notes() {
            return syncedSupabase({
                supabase,
                collection: 'notes',
                schema: 'other',
                filter: (select) => select.eq('body', 'a'),
            });
        }

        expectTypeOf<ReturnType<typeof notes>>().toEqualTypeOf<Record<string, NoteRow>>();
    });

    it('supports a database typed with its PostgREST version', () => {
        type DatabaseWithVersion = Database & { __InternalSupabase: { PostgrestVersion: '13.0.5' } };
        const supabase13 = {} as SupabaseClient<DatabaseWithVersion>;

        function todos() {
            return syncedSupabase({
                supabase: supabase13,
                collection: 'todos',
                filter: (select) => select.eq('done', true),
                select: (from) => from.select('id,text'),
            });
        }

        expectTypeOf<ReturnType<typeof todos>>().toEqualTypeOf<Record<number, { id: number; text: string }>>();
    });
});
